import{_ as l,o as a,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-12-08","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-12-08","date":"2021-12-08T00:00:00.000Z","updated":"2021-12-14T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","bluestore","bluefs","rocksdb","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","消除编码","复制","快照","克隆","瘦分配","iSCSI","Fibre Channel","NFS","CIFS","POSIX","监控","仪表板","管理","编排","自动化","集成","容器化","Kubernetes","Docker","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","拓扑","失败域","恢复","弹性","负载均衡","缓存","压缩","去重","分层","性能调优","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-12-08.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-12-08.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Crimson_SeaStore_2021-12-08.md"};function t(s,e,n,h,d,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间-2021年12月8日" tabindex="-1">会议时间：2021年12月8日 <a class="header-anchor" href="#会议时间-2021年12月8日" aria-label="Permalink to &quot;会议时间：2021年12月8日&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>逻辑PIN竞争修复</strong></p><ul><li>通过代码审查和发布版本，修复了逻辑PIN竞争问题。</li></ul></li><li><p><strong>心跳空白IP问题</strong></p><ul><li>解决了心跳中的空白IP问题，原因是测试中<code>self.configure</code>文件未设置为公共IP地址和集群IP地址。</li></ul></li><li><p><strong>Messenger单元测试进展</strong></p><ul><li>正在准备Messenger单元测试，已向团队成员发送邮件征求意见。</li></ul></li><li><p><strong>Rook集群安装问题</strong></p><ul><li>尝试安装Rook集群时遇到问题，已与Radic同步并获取输入，预计下周继续测试。</li></ul></li><li><p><strong>性能分析与优化</strong></p><ul><li>进行了性能分析，发现CPU时间主要被LBA研究占用，实施了一些优化并提交了PR。</li><li>观察到OMAP相关操作占用大量CPU时间，但目前不是重点。</li><li>GC速度影响性能，建议增加GC速度以提升性能。</li></ul></li><li><p><strong>日志相关功能测试</strong></p><ul><li>进行了日志相关功能的测试，发现清理操作与模拟和读取操作存在冲突。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续优化LBA和OMAP查找。</li><li>关注GC性能，作为下一步工作重点。</li><li>完善日志相关功能的指标，特别是清理、修剪和回收事务的区分。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>完成Messenger单元测试的准备工作。</li><li>继续Rook集群的安装和测试。</li><li>实施LBA和OMAP查找的优化。</li><li>增加GC速度以提升性能。</li><li>完善日志相关功能的指标。</li></ul><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li>会议记录者将在下周至1月3日期间休假，1月4日恢复工作，期间可通过邮件联系。</li></ul><h4 id="会议结束时间-具体时间" tabindex="-1">会议结束时间：[具体时间] <a class="header-anchor" href="#会议结束时间-具体时间" aria-label="Permalink to &quot;会议结束时间：[具体时间]&quot;">​</a></h4>',12)])])}const _=l(r,[["render",t]]);export{p as __pageData,_ as default};
